// Nessacord's look. Work in progress: for now this only loads the embedded font, lace, photo and
// mark (assets.css, generated by tools/make-assets.py). The theme rules come next.

import { disableStyle, enableStyle } from "@api/Styles";
import definePlugin from "@utils/types";

import assetsStyle from "./assets.css?managed";

export default definePlugin({
    name: "NessacordTheme",
    description: "Nessacord's black, lace and serif look.",
    authors: [{ name: "deargod", id: 0n }, { name: "bella", id: 0n }],
    enabledByDefault: true,

    start() {
        enableStyle(assetsStyle);
    },

    stop() {
        disableStyle(assetsStyle);
    }
});
